import{_ as a,o as s,c as o,a6 as i}from"./chunks/framework.CKIbuWFA.js";const p=JSON.parse('{"title":"Perguntas frequentes","description":"","frontmatter":{"title":"Perguntas frequentes","docId":"user.preferences.faq","translationKey":"user.preferences.faq","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"efa3a64ab4d688fd7650801112a8d3200f2d685b223735f39c9163dbf095e6c4","translationRevision":"34accedc262f929fb125828a38ac205193d9a3241cff94302eadf2347ce608ad","order":40},"headers":[],"relativePath":"pt/user/preferences/faq.md","filePath":"pt/user/preferences/faq.md","lastUpdated":1794611623000}'),t={name:"pt/user/preferences/faq.md"};function r(n,e,d,c,l,u){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="frequently-asked-questions" tabindex="-1">Perguntas frequentes <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Perguntas frequentes {#frequently-asked-questions}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Resolva confusões comuns de fluxo antes de alterar dados ou credenciais. Você precisa do aplicativo de desktop em execução para as verificações abaixo; <a href="./../requirements.html">requisitos</a> descreve os pacotes compatíveis. Os recursos locais discutidos aqui estão disponíveis, salvo quando houver um limite experimental ou dependente de serviço declarado.</p><h2 id="does-cloud-sign-in-connect-tiktok" tabindex="-1">O login no Cloud conecta o TikTok? <a class="header-anchor" href="#does-cloud-sign-in-connect-tiktok" aria-label="Permalink to &quot;O login no Cloud conecta o TikTok? {#does-cloud-sign-in-connect-tiktok}&quot;">​</a></h2><p>Não. Abra <a href="./../live/connections.html">Connections</a>, escolha um criador e inicie a LIVE separadamente. A identidade do Cloud dá suporte a serviços baseados em conta. Um cookie do TikTok pertence apenas ao campo mascarado de conexão destinado a ele.</p><h2 id="why-is-a-connected-feed-empty" tabindex="-1">Por que um feed conectado está vazio? <a class="header-anchor" href="#why-is-a-connected-feed-empty" aria-label="Permalink to &quot;Por que um feed conectado está vazio? {#why-is-a-connected-feed-empty}&quot;">​</a></h2><p>Uma sala silenciosa pode não ter eventos novos. Escolha todos os eventos, limpe a pesquisa e retome a rolagem, depois inspecione o status da conexão. Pausar a rolagem mantém ingestão e automações em execução. Limpar o feed não redefine pontos nem análises persistidas.</p><h2 id="are-statistics-only-for-this-session" tabindex="-1">As estatísticas são apenas desta sessão? <a class="header-anchor" href="#are-statistics-only-for-this-session" aria-label="Permalink to &quot;As estatísticas são apenas desta sessão? {#are-statistics-only-for-this-session}&quot;">​</a></h2><p>A <a href="./../points/statistics.html">página Analytics</a> atual consulta agregados persistidos do criador e intervalo de datas selecionados. Amplie as datas e atualize para inspecionar o histórico registrado. Não é uma transcrição completa do chat. Saldos de pontos usam regras diferentes e podem incluir ajustes manuais ou de automações.</p><h2 id="where-are-templates-variables-and-rankings" tabindex="-1">Onde ficam modelos, variáveis e rankings? <a class="header-anchor" href="#where-are-templates-variables-and-rankings" aria-label="Permalink to &quot;Onde ficam modelos, variáveis e rankings? {#where-are-templates-variables-and-rankings}&quot;">​</a></h2><p>Modelos e perfis ficam em <a href="./../automations/templates.html">Automations</a>; Explore de Plugins solicita plugins. Valores de execução ficam em Variables de Automations. A área experimental Rankings ainda tem <code>#/rankings</code>, mas fica oculta na navegação principal e na restauração inicial. Classificações comuns de pontos e painéis de ranking do feed continuam sendo visualizações separadas.</p><h2 id="does-saving-synchronize-everything" tabindex="-1">Salvar sincroniza tudo? <a class="header-anchor" href="#does-saving-synchronize-everything" aria-label="Permalink to &quot;Salvar sincroniza tudo? {#does-saving-synchronize-everything}&quot;">​</a></h2><p>Não. Changes de Events/Actions compara uma referência local. Salvar Variables permanece local, com operações separadas e revisadas de enviar/adotar/retirar quando compatíveis. Comparações de segredos são mascaradas. Overlays do Cloud usam criação/revisão e operações de biblioteca; esta versão não tem adaptador compartilhado Changes de overlays. Leia <a href="./../cloud/changes.html">Changes</a> antes de escolher uma direção.</p><h2 id="are-tests-harmless-and-do-imports-run-immediately" tabindex="-1">Os testes são inofensivos e as importações executam imediatamente? <a class="header-anchor" href="#are-tests-harmless-and-do-imports-run-immediately" aria-label="Permalink to &quot;Os testes são inofensivos e as importações executam imediatamente? {#are-tests-harmless-and-do-imports-run-immediately}&quot;">​</a></h2><p>Testes podem executar efeitos, incluindo áudio, requisições de rede e alterações de pontos. Comece com <a href="./../automations/first-rule.html">core.log</a>. Definições importadas permanecem desativadas; revise e ative explicitamente. Instalar um plugin também exige configurar seu serviço antes de suas ações funcionarem.</p><h2 id="expected-result-and-recovery" tabindex="-1">Resultado esperado e recuperação <a class="header-anchor" href="#expected-result-and-recovery" aria-label="Permalink to &quot;Resultado esperado e recuperação {#expected-result-and-recovery}&quot;">​</a></h2><p>Essas verificações devem identificar a página responsável sem uma redefinição. Verificações automáticas de atualização são opcionais; a instalação é experimental e está desativada pelos controles de lançamento atuais. Colaboração remota completa e busca de apelidos em produção ainda dependem de implantação e aceitação. Se a dúvida persistir, preserve seus dados por <a href="./backups.html">backups</a> e colete um <a href="./troubleshooting.html">relatório de diagnóstico</a> com versão, horário e reprodução.</p>',17)])])}const h=a(t,[["render",r]]);export{p as __pageData,h as default};
